DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.pm_ensure_timesheet_task(uuid,uuid)'::regprocedure) INTO definition; definition:=replace(definition,' OR public.is_psa_staff());',');'); definition:=replace(definition,'WHERE a.resource_id=me AND a.stage_id=_stage_id ORDER BY a.created_at,a.id LIMIT 1;','WHERE a.resource_id=me AND a.stage_id=_stage_id AND NOT coalesce(a.is_locked,false) AND a.external_id IS NULL AND coalesce(a.source,'''') NOT ILIKE ''%import%'' ORDER BY a.created_at,a.id LIMIT 1;'); EXECUTE definition; SELECT pg_get_functiondef('public.pm_prepare_planning_cutoff(text,uuid[])'::regprocedure) INTO definition; definition:=replace(definition,'p:=public.pm_planning_cutoff_preview', 'LOCK TABLE pm_projects,pm_stages,pm_allocations,pm_tasks,pm_time_entries,holidays,pm_week_publications IN SHARE MODE;'||chr(10)||' p:=public.pm_planning_cutoff_preview'); EXECUTE definition; END $$;